{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "What is the objective of this packing plan — are we minimizing the number of containers used, maximizing the total tons of goods shipped, or something else?"
  ],
  "rationale": "The response asks for a single policy choice regarding the optimization objective, presenting mutually exclusive options within one sentence."
}

{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "Do all available goods have to be shipped in this plan, or is it acceptable to leave some units of any type unshipped?"
  ],
  "rationale": "The response asks a single clarification question regarding whether all goods must be shipped or if unshipped units are allowed."
}

{
  "action": "question",
  "question_count": 1,
